            unresolved: m.unresolved.clone(),
            extra: Default::default(),
        },
        None => Coordinator {
            provider: None,
            model: None,
            engine: None,
            host: host.to_string(),
            source: if host == "unknown" {
                "none"
            } else {
                "inferred"
            }
            .to_string(),
            in_roster: None,
            unresolved: None,
            extra: Default::default(),
