    let (_, host) = c3_core::config::canonical_base_url(base_url);
    let host = host.trim_end_matches('.');
    if host.is_empty() || host.starts_with('[') {
        return None;
    }
    VENDORS
        .iter()
        .chain(std::iter::once(&OPENROUTER))
        .find(|v| {
            v.hosts
